/**
 * JSON-style ("mcp.json") MCP server configurations, as used by tools such as
 * Claude Desktop, Cursor, and Cline. `mcpServers` is an object keyed by the
 * server name, whereas Continue's YAML format uses a list of objects that each
 * carry their own `name` field.
 */
export interface StdioJsonMcpServerConfig {
  type?: "stdio";
  command: string;
  args?: string[];
  env?: Record<string, string>;
  envFile?: string;
}

export interface SseJsonMcpServerConfig {
  type?: "sse";
  url: string;
  headers?: Record<string, string>;
}

export interface HttpJsonMcpServerConfig {
  type: "http" | "streamable-http";
  url: string;
  headers?: Record<string, string>;
}

export type JsonMcpServerConfig =
  | StdioJsonMcpServerConfig
  | SseJsonMcpServerConfig
  | HttpJsonMcpServerConfig;

export interface McpServersJsonConfigFile {
  mcpServers: Record<string, JsonMcpServerConfig>;
}

/**
 * Replace `${VAR_NAME}` references with the YAML secret syntax
 * `${{ secrets.VAR_NAME }}`.
 */
function convertEnvVarsToYaml(
  env: Record<string, string>,
): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(env)) {
    result[key] = String(value).replace(
      /\$\{([A-Za-z0-9_]+)\}/g,
      "${{ secrets.$1 }}",
    );
  }
  return result;
}

/**
 * Replace the YAML `${{ secrets.VAR_NAME }}` and `${{ inputs.VAR_NAME }}`
 * syntaxes with the plain `${VAR_NAME}` syntax used by JSON configs.
 */
function convertSecretRefToJson(value: string): string {
  return String(value).replace(
    /\$\{\{\s*(?:secrets|inputs)\.([A-Za-z0-9_]+)\s*\}\}/g,
    "${$1}",
  );
}

function convertRecordRefsToJson(
  record: Record<string, string>,
): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(record)) {
    result[key] = convertSecretRefToJson(value);
  }
  return result;
}

/**
 * Convert a single JSON-style MCP server config into a Continue YAML-style
 * MCP server config.
 */
export function convertJsonMcpConfigToYamlMcpConfig(
  name: string,
  jsonConfig: JsonMcpServerConfig,
): { yamlConfig: MCPServer; warnings: string[] } {
  const warnings: string[] = [];
  const config = jsonConfig as any;

  // STDIO
  if (typeof config?.command === "string" || config?.type === "stdio") {
    if (config.envFile !== undefined) {
      warnings.push("envFile is not supported");
    }

    const yamlConfig: MCPServer = {
      name,
      type: "stdio",
      command: config.command,
    };
    if (config.args !== undefined) {
      yamlConfig.args = config.args;
    }
    if (config.env !== undefined) {
      yamlConfig.env = convertEnvVarsToYaml(config.env);
    }

    return { yamlConfig, warnings };
  }

  // SSE / HTTP
  if (typeof config?.url === "string") {
    const isHttp =
      config.type === "http" || config.type === "streamable-http";

    const yamlConfig: MCPServer = {
      name,
      url: config.url,
    };
    if (isHttp) {
      yamlConfig.type = "streamable-http";
    }
    if (config.headers !== undefined) {
      yamlConfig.requestOptions = { headers: config.headers };
    }

    return { yamlConfig, warnings };
  }

  throw new Error("Invalid MCP server configuration");
}

/**
 * Convert a Continue YAML-style MCP server config back into a JSON-style MCP
 * server config, collecting warnings for any fields that cannot be represented.
 */
export function convertYamlMcpConfigToJsonMcpConfig(yamlConfig: MCPServer): {
  name: string;
  jsonConfig: JsonMcpServerConfig;
  MCP_TIMEOUT: string | undefined;
  warnings: string[];
} {
  const warnings: string[] = [];
  const config = yamlConfig as any;
  const name: string = config.name;

  // STDIO
  if (config.type === "stdio" || typeof config.command === "string") {
    if (config.cwd !== undefined) {
      warnings.push("cwd is not supported");
    }
    if (config.faviconUrl !== undefined) {
      warnings.push("faviconUrl is not supported");
    }

    const jsonConfig: any = {
      type: "stdio",
      command: config.command,
    };
    if (config.args !== undefined) {
      jsonConfig.args = config.args;
    }
    if (config.env !== undefined) {
      jsonConfig.env = convertRecordRefsToJson(config.env);
    }

    const MCP_TIMEOUT =
      config.connectionTimeout !== undefined
        ? String(config.connectionTimeout)
        : undefined;

    return { name, jsonConfig, MCP_TIMEOUT, warnings };
  }

  // SSE / HTTP
  if (typeof config.url === "string") {
    const jsonConfig: any = {
      type: config.type === "streamable-http" ? "http" : "sse",
      url: config.url,
    };

    const requestOptions = config.requestOptions;
    if (requestOptions) {
      if (requestOptions.headers !== undefined) {
